void testReplaceAll() {
    assumeTrue(isSetValueSupported() && isReplaceAllSupported());
    resetFull();
    final V[] newValues = getNewSampleValues();
    assertFalse(getMap().isEmpty());
    getMap().replaceAll((k, v) -> v);
