    final AtomicInteger i = new AtomicInteger();
    final Map<K, V> newMap = new HashMap<>();
    getMap().replaceAll((k, v) -> {
        final V v2 = newValues[i.getAndIncrement()];
        newMap.put(k, v2);
        return v2;
    });
    assertEquals(newMap, getMap());
}

